from taf.ul.mobile.ui.android.adb_proxy.adb_proxy import AdbProxy


class Android14AdbProxy(AdbProxy):

    def force_stop_setting(self):
        self._executor.execute(
            self._construct_command("adb shell am force-stop com.android.settings.intelligence"))

        self._executor.execute(
            self._construct_command("adb shell am force-stop com.android.settings"))
